ruleBookInfo.lastChapter:
@js:
var s = String(result);
var m = s.match(/Html = "(.*?)"/);
if (!m) { ''; } else {
    var d = unescape(m[1]);
    var a = d.match(/chapterName='([^']*)'/g) || [];
    var t = a.length ? a[a.length - 1].replace(/^chapterName='/, '').replace(/'$/, '') : '';
    t;
}

ruleContent.content:
@js:
var s = String(result);
// 1) 懒加载还原：真实地址在 specialdata-src，src 只是 refresh.png 占位图
s = s.replace(/<img([^>]*)>/g, function (m0, attrs) {
    var rm = attrs.match(/\sspecialdata-src="([^"]+)"/);
    if (!rm) return m0;
    attrs = attrs.replace(/\sspecialdata-src="[^"]*"/g, '').replace(/\ssrc="[^"]*"/g, '');
    return '<img' + attrs + ' src="' + rm[1] + '">';
});
// 2) 提取正文容器 ztArtCon（div 配平，兼容嵌套）
var m = s.match(/<div[^>]*class=["']ztArtCon["'][^>]*>/i);
var html;
if (m) {
    var start = m.index, depth = 0, end = s.length;
    var re = /<\/?div\b/g;
    re.lastIndex = start;
    var mm;
    while ((mm = re.exec(s)) !== null) {
        depth += (mm[0].charAt(1) === '/') ? -1 : 1;
        if (depth === 0) { end = mm.index + mm[0].length; break; }
    }
    html = s.substring(start + m[0].length, Math.max(start + m[0].length, end - 6));
} else {
    var b = s.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    html = b ? b[1] : s;
}
// 3) 清理：空锚点、脚本、样式
html = html.replace(/<a[^>]*>\s*<\/a>/g, '')
           .replace(/<script[\s\S]*?<\/script>/gi, '')
           .replace(/<style[\s\S]*?<\/style>/gi, '');
// 4) 长段自动断行（保留原书源排版行为）
html = html.replace(/([\w，、。！？]{26}[。！？；]+[”’]?)(?=[^\n]{27})/g, '$1<br>');
// 5) 版权保护章节（btype=tushu）正文不公开，给出提示而非空白
var txt = html.replace(/<[^>]+>/g, '').replace(/\s/g, '');
if (txt.length < 10 && html.indexOf('prevChapter') > -1) {
    html = '【本章无法获取正文】该章节属于超星版权保护内容（图书类），站点仅在客户端内提供正文。';
}
html;
